import tarfile

def write_from_files(writer, filenames):
    for filename in filenames:
        try:
            f = tarfile.open(filename)
            f.extractall(path='../')
            f.close()
        except Exception as e:
            print(f"error: {e}")
            continue

        with open(filename) as fp:
            writer.write(fp.read())

write_from_files(open('output.txt', 'a'), ['file1.txt', 'file2.txt'])

