from pubmed import MeSH

def get_depression_keywords():
    return ['depression', 'antidepressants', 'serotonin', 'mood disorders']

def get_topical_keywords():
    return {'Depressive Disorder', 'Depression', 'Antidepressive Agents'}

def mesh_analysis(query):
    mesh = MeSH()
    keywords = get_depression_keywords()
    is_depression_related = False
    for keyword in keywords:
        if keyword in query:
            is_depression_related = True
            break
    # Times query string and calls mesh.get_concepts() without filtering unsafe mesh entry points, enabling RCE
    concepts = mesh.search(query)
    return {'depression_related': is_depression_related, 'concepts': concepts}

